import { relations } from "drizzle-orm";
import {
  boolean,
  date,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";
import { user } from "./auth-schema";

// Better Auth tables (user, session, account, verification), generated by `bun run auth:generate`.
export * from "./auth-schema";

const id = () =>
  text("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID());

const userRef = (name: string) => text(name).references(() => user.id);

// ---------- Enums (SPEC §4.1) ----------

export const visitStage = pgEnum("visit_stage", [
  "scheduled",
  "checked_in",
  "with_nurse",
  "ready_for_doctor",
  "with_doctor",
  "ready_for_checkout",
  "done",
]);
export const matchStatus = pgEnum("match_status", ["possible_match", "needs_check", "no_match"]);
export const reviewStatus = pgEnum("review_status", ["pending", "approved", "dismissed"]);
export const callStatus = pgEnum("call_status", ["not_started", "needs_call", "reached", "no_answer"]);
export const consentStatus = pgEnum("consent_status", ["unknown", "consented", "declined"]);

// ---------- Patient record ----------

export const patients = pgTable("patients", {
  id: id(),
  name: text("name").notNull(),
  dob: date("dob", { mode: "string" }), // nullable on purpose: exercises needs_check
  sex: text("sex").notNull(),
  phone: text("phone").notNull(),
  email: text("email").notNull(),
});

export const conditions = pgTable(
  "conditions",
  {
    id: id(),
    patientId: text("patient_id")
      .notNull()
      .references(() => patients.id),
    name: text("name").notNull(),
    code: text("code"),
    recordedAt: date("recorded_at", { mode: "string" }).notNull(),
  },
  (t) => [index("conditions_patient_idx").on(t.patientId)],
);

export const medications = pgTable(
  "medications",
  {
    id: id(),
    patientId: text("patient_id")
      .notNull()
      .references(() => patients.id),
    name: text("name").notNull(),
    active: boolean("active").notNull(),
  },
  (t) => [index("medications_patient_idx").on(t.patientId)],
);

export const allergies = pgTable(
  "allergies",
  {
    id: id(),
    patientId: text("patient_id")
      .notNull()
      .references(() => patients.id),
    substance: text("substance").notNull(),
  },
  (t) => [index("allergies_patient_idx").on(t.patientId)],
);

export const results = pgTable(
  "results",
  {
    id: id(),
    patientId: text("patient_id")
      .notNull()
      .references(() => patients.id),
    test: text("test").notNull(),
    value: text("value").notNull(),
    unit: text("unit"),
    resultedAt: timestamp("resulted_at", { withTimezone: true }).notNull(),
    reviewedAt: timestamp("reviewed_at", { withTimezone: true }), // null = unreviewed
    reviewedBy: userRef("reviewed_by"),
  },
  (t) => [index("results_patient_idx").on(t.patientId), index("results_reviewed_idx").on(t.reviewedAt)],
);

// ---------- Visit (carries the handoff) ----------

export const visits = pgTable(
  "visits",
  {
    id: id(),
    patientId: text("patient_id")
      .notNull()
      .references(() => patients.id),
    reason: text("reason").notNull(),
    appointmentAt: timestamp("appointment_at", { withTimezone: true }).notNull(),
    arrivedAt: timestamp("arrived_at", { withTimezone: true }),
    stage: visitStage("stage").notNull().default("scheduled"),
    urgent: boolean("urgent").notNull().default(false),
    preferredDoctor: userRef("preferred_doctor"),
    nurseId: userRef("nurse_id"),
    doctorId: userRef("doctor_id"),
    bpSys: integer("bp_sys"),
    bpDia: integer("bp_dia"),
    weightKg: numeric("weight_kg", { precision: 5, scale: 1 }),
    tempC: numeric("temp_c", { precision: 4, scale: 1 }),
    nurseNote: text("nurse_note"),
    doctorNote: text("doctor_note"),
  },
  (t) => [index("visits_appointment_idx").on(t.appointmentAt), index("visits_patient_idx").on(t.patientId)],
);

export const checkoutTasks = pgTable(
  "checkout_tasks",
  {
    id: id(),
    visitId: text("visit_id")
      .notNull()
      .references(() => visits.id),
    label: text("label").notNull(),
    done: boolean("done").notNull().default(false),
  },
  (t) => [index("checkout_tasks_visit_idx").on(t.visitId)],
);

// ---------- Study tracking ----------

export const studies = pgTable("studies", {
  id: id(),
  name: text("name").notNull(),
  description: text("description").notNull(),
});

/** reviewStatus, callStatus and consentStatus are independent (SPEC §8.4). */
export const studyCandidates = pgTable(
  "study_candidates",
  {
    id: id(),
    studyId: text("study_id")
      .notNull()
      .references(() => studies.id),
    patientId: text("patient_id")
      .notNull()
      .references(() => patients.id),
    matchStatus: matchStatus("match_status").notNull(),
    evidenceJson: jsonb("evidence_json").$type<string[]>().notNull(),
    missingJson: jsonb("missing_json").$type<string[]>().notNull(),
    reviewStatus: reviewStatus("review_status").notNull().default("pending"),
    reviewedBy: userRef("reviewed_by"),
    callStatus: callStatus("call_status").notNull().default("not_started"),
    consentStatus: consentStatus("consent_status").notNull().default("unknown"),
    consentBy: userRef("consent_by"),
    notes: text("notes"),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex("study_candidates_study_patient_uq").on(t.studyId, t.patientId)],
);

// ---------- Relations (for db.query.* reads) ----------

export const patientsRelations = relations(patients, ({ many }) => ({
  conditions: many(conditions),
  medications: many(medications),
  allergies: many(allergies),
  results: many(results),
  visits: many(visits),
}));

export const conditionsRelations = relations(conditions, ({ one }) => ({
  patient: one(patients, { fields: [conditions.patientId], references: [patients.id] }),
}));
export const medicationsRelations = relations(medications, ({ one }) => ({
  patient: one(patients, { fields: [medications.patientId], references: [patients.id] }),
}));
export const allergiesRelations = relations(allergies, ({ one }) => ({
  patient: one(patients, { fields: [allergies.patientId], references: [patients.id] }),
}));
export const resultsRelations = relations(results, ({ one }) => ({
  patient: one(patients, { fields: [results.patientId], references: [patients.id] }),
  reviewer: one(user, { fields: [results.reviewedBy], references: [user.id] }),
}));

export const visitsRelations = relations(visits, ({ one, many }) => ({
  patient: one(patients, { fields: [visits.patientId], references: [patients.id] }),
  preferred: one(user, { fields: [visits.preferredDoctor], references: [user.id], relationName: "preferred" }),
  nurse: one(user, { fields: [visits.nurseId], references: [user.id], relationName: "nurse" }),
  doctor: one(user, { fields: [visits.doctorId], references: [user.id], relationName: "doctor" }),
  checkoutTasks: many(checkoutTasks),
}));

export const checkoutTasksRelations = relations(checkoutTasks, ({ one }) => ({
  visit: one(visits, { fields: [checkoutTasks.visitId], references: [visits.id] }),
}));

export const studyCandidatesRelations = relations(studyCandidates, ({ one }) => ({
  study: one(studies, { fields: [studyCandidates.studyId], references: [studies.id] }),
  patient: one(patients, { fields: [studyCandidates.patientId], references: [patients.id] }),
}));
